      const percent = Math.floor(processedCount / tileCount * 100);
      onProgress(`生成瓦片 (${processedCount}/${tileCount}): ${percent}%`);
      const filename = `tile_${path}.glb`;
      fileBlobs.set(filename, new Blob([glbBuffer], { type: "model/gltf-binary" }));
      tileObj.content = {
        uri: filename
      };
