async function exportGLB(root) {
  const exporter = new GLTFExporter();
  return new Promise((resolve, reject) => {
    exporter.parse(
      root,
      (result) => {
        const blob = new Blob([result], { type: "model/gltf-binary" });
        resolve(blob);
      },
      (err) => reject(err),
      { binary: true }
    );
  });
}
